  ('g1-c2-l4', 'g1-c2', 'Bài 4: Hình chữ nhật', 'learn', 'Nhận biết hình chữ nhật và phân biệt với hình vuông', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Quyển sách của bé có bốn cạnh, nhưng hai cạnh dài hơn hai cạnh kia. Đó là hình gì? 📕","shapePicture":{"kind":"book","note":"Quyển sách có dạng hình chữ nhật"}}},{"type":"concept","content":{"badge":"Khám Phá","title":"Hình chữ nhật","explanation":"HÌNH CHỮ NHẬT có 4 cạnh: hai cạnh DÀI bằng nhau và hai cạnh NGẮN bằng nhau.","rule":"Hình chữ nhật có 4 cạnh, 4 đỉnh. Hai cạnh dài bằng nhau, hai cạnh ngắn bằng nhau.","points":["Quyển sách, cửa ra vào, mặt bàn có dạng hình chữ nhật.","Hình chữ nhật khác hình vuông: 2 cạnh dài bằng nhau, 2 cạnh ngắn bằng nhau.","Cả hai đều có 4 cạnh, 4 đỉnh."]}},{"type":"visual","content":{"text":"Hình chữ nhật: 2 cạnh dài bằng nhau · 2 cạnh ngắn bằng nhau","planeShape":{"kind":"rectangle","labels":["chiều dài","chiều rộng"],"formula":"2 cạnh dài bằng nhau · 2 cạnh ngắn bằng nhau"}}},{"type":"quiz","content":{"question":"Hình chữ nhật khác hình vuông ở điểm nào?","planeShapes":[{"kind":"square"},{"kind":"rectangle"}],"options":["Chỉ hai cạnh dài bằng nhau và hai cạnh ngắn bằng nhau","Có ba cạnh","Không có đỉnh","Có đường bao cong"],"answer":"Chỉ hai cạnh dài bằng nhau và hai cạnh ngắn bằng nhau","mascotHint":"Hình vuông có 4 cạnh bằng nhau; hình chữ nhật thì không."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Hình chữ nhật có 4 cạnh, 4 đỉnh.","Hai cạnh dài bằng nhau, hai cạnh ngắn bằng nhau."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g1-c2-l5', 'g1-c2', 'Bài 5: Nhận biết các hình trong đồ vật quanh em', 'learn', 'Tìm các hình đã học trong đồ vật thực tế', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Rô-bốt đi một vòng quanh nhà và tìm được rất nhiều hình! Bé cùng tìm nhé 🔍"}},{"type":"concept","content":{"badge":"Thực Hành","title":"Hình ở quanh em","explanation":"Các hình phẳng có ở khắp nơi quanh bé. Bé nhìn và gọi tên hình của đồ vật.","rule":"Mặt đồng hồ tròn → hình tròn. Viên gạch vuông → hình vuông. Mái nhà → hình tam giác. Quyển sách → hình chữ nhật.","points":["Hình tròn: bánh xe, cái đĩa, mặt đồng hồ.","Hình vuông: viên gạch hoa, khung ảnh vuông.","Hình tam giác: mái nhà, biển báo.","Hình chữ nhật: cửa ra vào, mặt bàn, quyển sách."]}},{"type":"quiz","content":{"question":"Mặt đồng hồ có dạng hình gì?","shapePicture":{"kind":"clock","showShape":false},"options":["Hình tròn","Hình vuông","Hình tam giác","Hình chữ nhật"],"answer":"Hình tròn","mascotHint":"Mặt đồng hồ có đường bao cong, không có cạnh — đấy là hình tròn."}},{"type":"quiz","content":{"question":"Viên gạch lát nền có dạng hình gì?","shapePicture":{"kind":"brick","showShape":false},"options":["Hình vuông","Hình tròn","Hình chữ nhật","Hình tam giác"],"answer":"Hình vuông","mascotHint":"Viên gạch có bốn cạnh dài bằng nhau — hình vuông."}},{"type":"quiz","content":{"question":"Mái nhà có dạng hình gì?","shapePicture":{"kind":"roof","showShape":false},"options":["Hình tam giác","Hình vuông","Hình tròn","Hình chữ nhật"],"answer":"Hình tam giác","mascotHint":"Mái nhà có ba cạnh — hình tam giác."}},{"type":"quiz","content":{"question":"Quyển sách có dạng hình gì?","shapePicture":{"kind":"book","showShape":false},"options":["Hình chữ nhật","Hình vuông","Hình tam giác","Hình tròn"],"answer":"Hình chữ nhật","mascotHint":"Quyển sách có hai cạnh dài và hai cạnh ngắn — hình chữ nhật."}},{"type":"visual","content":{"text":"Bé nhìn đồ vật và gọi tên hình của nó","table":{"headers":["Đồ vật","Có dạng hình"],"rows":[["Mặt đồng hồ","Hình tròn"],["Viên gạch lát nền","Hình vuông"],["Mái nhà","Hình tam giác"],["Quyển sách","Hình chữ nhật"]],"label":"Tìm hình trong đồ vật quanh em"}}},{"type":"quiz","content":{"question":"Bánh xe đạp có dạng hình gì?","shapePicture":{"kind":"wheel","note":"Bánh xe có dạng hình tròn"},"options":["Hình tròn","Hình vuông","Hình tam giác","Hình chữ nhật"],"answer":"Hình tròn","mascotHint":"Bánh xe tròn và lăn được — hình tròn."}},{"type":"quiz","content":{"question":"Cửa ra vào của lớp học có dạng hình gì?","shapePicture":{"kind":"door","note":"Cửa ra vào có dạng hình chữ nhật"},"options":["Hình chữ nhật","Hình tròn","Hình tam giác","Hình vuông"],"answer":"Hình chữ nhật","mascotHint":"Cửa cao hơn bề ngang nên là hình chữ nhật."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Bé nhận ra hình tròn, hình vuông, hình tam giác, hình chữ nhật.","Các hình có ở khắp nơi quanh bé."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g1-c2-l6', 'g1-c2', 'Bài 6: Thực hành lắp ghép, xếp hình', 'learn', 'Dùng các hình đã học để xếp thành hình mới', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Rô-bốt ghép hai hình tam giác thành một hình vuông! Bé thử xem được không nhé 🔷","shapeJoin":{"piece":"rightTriangle","pieces":2,"note":"Hai tam giác vuông ghép lại thành một hình vuông"}}},{"type":"concept","content":{"badge":"Thực Hành","title":"Ghép hình","explanation":"Bé có thể ghép nhiều hình nhỏ thành một hình lớn hơn, hoặc cắt một hình thành nhiều hình nhỏ.","rule":"Hai hình tam giác ghép lại có thể được một hình vuông.","points":["Ghép hai tam giác → một hình vuông.","Ghép bốn hình vuông nhỏ → một hình vuông lớn.","Dùng bộ xếp hình để thử nhiều cách khác nhau."],"shapeJoin":{"piece":"rightTriangle","pieces":2,"note":"Hai tam giác vuông ghép lại thành một hình vuông"}}},{"type":"visual","content":{"text":"Ghép 2 tam giác vuông → 1 hình vuông","shapeJoin":{"piece":"rightTriangle","pieces":2,"note":"Hai tam giác vuông ghép lại thành một hình vuông"}}},{"type":"visual","content":{"text":"Ghép 4 hình vuông nhỏ → 1 hình vuông lớn","shapeJoin":{"piece":"square","pieces":4,"note":"Bốn hình vuông nhỏ ghép lại thành một hình vuông lớn"}}},{"type":"visual","content":{"planeShape":{"kind":"square","vertices":true,"vertexLabel":"đỉnh"},"text":"hình vuông bé học hôm nay có gì đặc biệt?\n· 4 cạnh dài bằng nhau\nBé đếm cạnh, đếm đỉnh ngay trên hình vẽ rồi đọc lại đặc điểm trên nhé."}},{"type":"concept","content":{"badge":"Ghi Nhớ","title":"Đặc điểm của hình vuông","explanation":"Nhìn hình và gọi tên đúng là bước đầu; bước sau là nêu được đặc điểm của hình vuông.","points":["hình vuông có 4 cạnh dài bằng nhau.","hình vuông có 4 cạnh dài bằng nhau.","hình vuông có 4 đỉnh.","Cách kiểm tra: bé đếm cạnh, đếm đỉnh; nếu đếm ra khác các đặc điểm trên thì đã nhìn nhầm hình."]}},{"type":"visual","content":{"table":{"headers":["Bước","Việc bé làm"],"rows":[["Bước 1 — Gọi tên","nhìn hình rồi nói đúng tên hình (hoặc khối)"],["Bước 2 — Đếm","đếm cạnh, đếm đỉnh rồi đọc lại hai đặc điểm của hình"],["Bước 3 — Kiểm lại","đếm lại lần nữa bằng mắt, không đoán"]]},"text":"Ba bước làm bài hình — bé làm lần lượt\nBé đọc bảng này trước khi làm, và đọc lại sau khi làm xong.\nBỏ một bước là bài dễ sai."}},{"type":"quiz","content":{"question":"Làm xong một bài, bé nên làm gì để chắc chắn kết quả đúng?","options":["Kiểm lại một lần nữa theo điều cần nhớ","Nộp bài luôn cho nhanh","Đoán lại một lần nữa"],"answer":"Kiểm lại một lần nữa theo điều cần nhớ","mascotHint":"Kiểm lại một lần nữa rồi mới nộp bài — kiểm lại là thói quen của người học giỏi."}},{"type":"quiz","content":{"question":"Hình nào có 4 cạnh dài bằng nhau?","options":["hình vuông","hình tròn","hình tam giác","hình chữ nhật"],"answer":"hình vuông","mascotHint":"hình vuông: 4 cạnh dài bằng nhau · 4 đỉnh."}},{"type":"quiz","content":{"question":"Trong bài hôm nay có hình vuông và hình tròn và hình tam giác. Hình nào có 4 cạnh dài bằng nhau?","options":["hình vuông","hình tròn","hình tam giác","hình chữ nhật"],"answer":"hình vuông","mascotHint":"Đáp án là hình vuông: 4 cạnh dài bằng nhau · 4 đỉnh."}},{"type":"quiz","content":{"question":"Hai hình tam giác giống nhau ghép lại có thể được hình gì?","options":["Hình vuông","Hình tròn","Hình tam giác lớn hơn nữa","Không được hình nào"],"answer":"Hình vuông","mascotHint":"Ghép hai tam giác giống nhau được một hình vuông.","shapeJoin":{"piece":"rightTriangle","pieces":2,"showResult":false,"note":"Hai tam giác vuông giống nhau — ghép lại sẽ được hình gì?"}}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Ghép hình nhỏ thành hình lớn.","Hai tam giác ghép được một hình vuông."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
