  ('g2-c5-l6', 'g2-c5', 'Bài 6: Hình tứ giác', 'learn', 'Nhận biết hình tứ giác và các đặc điểm của nó', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Rô-bốt cắt một hình có bốn cạnh. Bé đoán xem đó là hình gì? ✂️","planeShape":{"kind":"parallelogram","labels":["cạnh","cạnh"],"vertices":true,"showName":false,"formula":"Hình có 4 cạnh"}}},{"type":"concept","content":{"badge":"Khám Phá","title":"Hình tứ giác","explanation":"Hình TỨ GIÁC là hình có 4 cạnh và 4 đỉnh.","rule":"Hình tứ giác ABCD có 4 cạnh: AB, BC, CD, DA và 4 đỉnh: A, B, C, D.","points":["Mép bàn, viên gạch, mặt quyển sách đều có dạng tứ giác.","Hình vuông và hình chữ nhật cũng là hình tứ giác — loại đặc biệt.","Đếm kĩ: 4 cạnh, 4 đỉnh."],"planeShape":{"kind":"quad","labels":["AB","BC","CD","DA"],"vertexLabels":["A","B","C","D"],"formula":"Tứ giác ABCD: 4 cạnh, 4 đỉnh"}}},{"type":"visual","content":{"text":"Hình tứ giác ABCD: 4 cạnh AB, BC, CD, DA · 4 đỉnh A, B, C, D","planeShape":{"kind":"quad","labels":["AB","BC","CD","DA"],"vertexLabels":["A","B","C","D"],"formula":"4 cạnh: AB, BC, CD, DA · 4 đỉnh: A, B, C, D"}}},{"type":"quiz","content":{"question":"Hình tứ giác có mấy cạnh và mấy đỉnh?","options":["3 cạnh, 3 đỉnh","4 cạnh, 4 đỉnh","4 cạnh, 3 đỉnh","5 cạnh, 5 đỉnh"],"answer":"4 cạnh, 4 đỉnh","mascotHint":"''Tứ'' nghĩa là bốn: 4 cạnh và 4 đỉnh.","planeShapes":[{"kind":"rectangle","color":"#ec4899"}]}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Hình tứ giác có 4 cạnh và 4 đỉnh.","Hình vuông, hình chữ nhật cũng là hình tứ giác."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c13-l1', 'g2-c13', 'Bài 1: Thu thập và phân loại số liệu', 'learn', 'Biết cách thu thập số liệu và phân loại theo tiêu chí', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Cả lớp có bao nhiêu bạn thích màu đỏ, bao nhiêu bạn thích màu xanh? Làm sao biết nhỉ? 📊"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Thu thập và phân loại","explanation":"THU THẬP số liệu là hỏi và ghi lại thông tin. PHÂN LOẠI là xếp các thông tin đó vào từng nhóm theo một tiêu chí.","rule":"Hỏi từng bạn thích màu gì rồi xếp vào hai nhóm: nhóm màu đỏ và nhóm màu xanh.","points":["Tiêu chí phân loại phải rõ ràng: theo màu, theo loại quả, theo giới tính.","Mỗi thông tin chỉ thuộc một nhóm.","Thu thập xong thì mới đếm được."]}},{"type":"visual","content":{"text":"Ví dụ: hỏi các bạn trong lớp\nThích màu đỏ: 7 bạn\nThích màu xanh: 4 bạn\nMỗi bạn chỉ ở một nhóm","table":{"headers":["Nhóm","Số bạn"],"rows":[["Thích màu đỏ","7 bạn"],["Thích màu xanh","4 bạn"]],"label":"Ví dụ: hỏi các bạn trong lớp rồi xếp vào hai nhóm — mỗi bạn chỉ ở một nhóm"}}},{"type":"visual","content":{"table":{"headers":["Nhóm","Số bạn"],"rows":[["Thích màu đỏ","7 bạn"],["Thích màu xanh","4 bạn"]],"label":"Ví dụ: hỏi các bạn trong lớp rồi xếp vào hai nhóm — mỗi bạn chỉ ở một nhóm"},"text":"Bảng số liệu của bài — bé đọc theo HÀNG, không đọc theo cột\nMuốn biết “tất cả”, “nhiều nhất”, “ít nhất” thì phải cộng hoặc so các con số.\nVí dụ: 7 + 4 = 11."}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Cách đọc bảng số liệu","explanation":"Bảng số liệu là một bức tranh bằng số: mỗi hàng là một đối tượng, mỗi cột là một thông tin.","points":["Bước 1 — đọc tên hàng (hoặc cột đầu) để biết đang nói về cái gì.","Bước 2 — đọc con số ở cột tương ứng với đối tượng đó.","Bước 3 — muốn biết “tất cả”, “nhiều nhất”, “ít nhất” thì phải CỘNG hoặc SO các con số, không đọc lại một ô.","Kiểm tra lại: tổng vừa tính phải LỚN HƠN từng con số trong bảng."]}},{"type":"quiz","content":{"question":"Trong bảng trên, số lượng nào LỚN NHẤT?","options":[4,7,8,11],"answer":7,"mascotHint":"Bé so các con số 7, 4 — số lớn nhất là 7.","table":{"headers":["Nhóm","Số bạn"],"rows":[["Thích màu đỏ","7 bạn"],["Thích màu xanh","4 bạn"]]}}},{"type":"quiz","content":{"question":"Cộng các con số trong bảng lại thì được bao nhiêu?","options":[7,11,12,14],"answer":11,"mascotHint":"Lấy các con số cộng lại: 7 + 4 = 11.","table":{"headers":["Nhóm","Số bạn"],"rows":[["Thích màu đỏ","7 bạn"],["Thích màu xanh","4 bạn"]]}}},{"type":"quiz","content":{"question":"Phân loại các loại quả theo tiêu chí nào là hợp lí?","options":["Quả có màu đỏ và quả có màu vàng","Quả to và quả ngon","Quả và bàn ghế","Quả và bạn bè"],"answer":"Quả có màu đỏ và quả có màu vàng","mascotHint":"Tiêu chí phải rõ và mọi quả phải thuộc đúng một nhóm."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Thu thập số liệu là hỏi và ghi lại thông tin.","Phân loại là xếp thông tin vào các nhóm theo tiêu chí."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c13-l2', 'g2-c13', 'Bài 2: Kiểm đếm số liệu', 'learn', 'Dùng vạch hoặc ô để kiểm đếm số liệu', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Rô-bốt đếm số bạn thích mỗi màu bằng cách gạch từng vạch. Bé xem nhé! ✏️"}},{"type":"concept","content":{"badge":"Thực Hành","title":"Kiểm đếm bằng vạch","explanation":"Mỗi lần gặp một thông tin, bé gạch một vạch vào đúng nhóm. Cuối cùng đếm số vạch để biết số lượng.","rule":"Cứ 5 vạch thì gạch chéo một lần cho dễ đếm: |||| = 4; ||||/ = 5.","points":["Gạch theo nhóm 5 cho dễ đếm.","Đếm xong ghi số vào cạnh nhóm.","Kiểm đếm giúp biết nhóm nào nhiều nhất, nhóm nào ít nhất."]}},{"type":"visual","content":{"text":"Màu đỏ:   ||||/ ||   → 7 bạn\nMàu xanh: ||||      → 4 bạn","table":{"headers":["Màu","Số bạn"],"rows":[["Màu đỏ",7],["Màu xanh",4]],"label":"Kiểm đếm bằng vạch: cứ 5 vạch thì gạch chéo một lần"}}},{"type":"visual","content":{"cotTinh":{"left":7,"right":4,"sign":"−"},"text":"Bé tự đặt tính: 7 − 4\nhàng đơn vị 7 − 4 = 3, viết 3\nVậy 7 − 4 = 3."}},{"type":"visual","content":{"table":{"headers":["Màu","Số bạn"],"rows":[["Màu đỏ",7],["Màu xanh",4]],"label":"Kiểm đếm bằng vạch: cứ 5 vạch thì gạch chéo một lần"},"text":"Bảng số liệu của bài — bé đọc theo HÀNG, không đọc theo cột\nMuốn biết “tất cả”, “nhiều nhất”, “ít nhất” thì phải cộng hoặc so các con số.\nVí dụ: 7 + 4 = 11."}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Cách đọc bảng số liệu","explanation":"Bảng số liệu là một bức tranh bằng số: mỗi hàng là một đối tượng, mỗi cột là một thông tin.","points":["Bước 1 — đọc tên hàng (hoặc cột đầu) để biết đang nói về cái gì.","Bước 2 — đọc con số ở cột tương ứng với đối tượng đó.","Bước 3 — muốn biết “tất cả”, “nhiều nhất”, “ít nhất” thì phải CỘNG hoặc SO các con số, không đọc lại một ô.","Kiểm tra lại: tổng vừa tính phải LỚN HƠN từng con số trong bảng."]}},{"type":"quiz","content":{"question":"Trong bảng trên, số lượng nào LỚN NHẤT?","options":[4,7,8,11],"answer":7,"mascotHint":"Bé so các con số 7, 4 — số lớn nhất là 7.","table":{"headers":["Màu","Số bạn"],"rows":[["Màu đỏ",7],["Màu xanh",4]]}}},{"type":"quiz","content":{"question":"Cộng các con số trong bảng lại thì được bao nhiêu?","options":[7,11,12,14],"answer":11,"mascotHint":"Lấy các con số cộng lại: 7 + 4 = 11.","table":{"headers":["Màu","Số bạn"],"rows":[["Màu đỏ",7],["Màu xanh",4]]}}},{"type":"quiz","content":{"question":"8 − 5 bằng bao nhiêu?","options":[2,3,4,5],"answer":3,"mascotHint":"hàng đơn vị 8 − 5 = 3, viết 3. Kết quả 3."}},{"type":"quiz","content":{"question":"Nhóm A có 7 vạch, nhóm B có 4 vạch. Nhóm nào nhiều hơn và nhiều hơn mấy?","options":["Nhóm A, nhiều hơn 3","Nhóm B, nhiều hơn 3","Bằng nhau","Nhóm A, nhiều hơn 11"],"answer":"Nhóm A, nhiều hơn 3","mascotHint":"7 − 4 = 3, nên nhóm A nhiều hơn 3."}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Mỗi thông tin gạch một vạch vào đúng nhóm.","Gạch nhóm 5 cho dễ đếm."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g2-c13-l6', 'g2-c13', 'Bài 6: Luyện tập chung chủ đề 13', 'learn', 'Ôn tập thống kê và khả năng xảy ra', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Bé đã biết thu thập số liệu và đoán khả năng rồi! Tổng kết nhé 🎉"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Tổng kết chủ đề 13","explanation":"Bé đã học thu thập và phân loại số liệu, kiểm đếm, biểu đồ tranh và ba mức khả năng.","points":["Thu thập → phân loại → kiểm đếm → vẽ biểu đồ.","Biểu đồ tranh: mỗi hình tương ứng một số lượng.","Khả năng: chắc chắn, có thể, không thể."]}},{"type":"visual","content":{"text":"Thu thập → Phân loại → Kiểm đếm → Biểu đồ tranh","table":{"headers":["Bước","Việc làm"],"rows":[["1","Thu thập số liệu"],["2","Phân loại"],["3","Kiểm đếm"],["4","Vẽ biểu đồ tranh"]],"label":"Luyện tập chung chủ đề 13"}}},{"type":"visual","content":{"cotTinh":{"left":4,"right":5,"sign":"×","remember":true},"text":"Bé tự đặt tính: 4 × 5\nhàng đơn vị 4 × 5 = 20, viết 0 nhớ 2\ncòn nhớ 2 ở hàng cao hơn, viết 2\nVậy 4 × 5 = 20."}},{"type":"visual","content":{"table":{"headers":["Bước","Việc làm"],"rows":[["1","Thu thập số liệu"],["2","Phân loại"],["3","Kiểm đếm"]],"label":"Luyện tập chung: 3 bước đầu"},"text":"Bảng số liệu của bài — bé đọc theo HÀNG, không đọc theo cột\nMuốn biết “tất cả”, “nhiều nhất”, “ít nhất” thì phải cộng hoặc so các con số.\nVí dụ: 1 + 2 + 3 = 6."}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Cách đọc bảng số liệu","explanation":"Bảng số liệu là một bức tranh bằng số: mỗi hàng là một đối tượng, mỗi cột là một thông tin.","points":["Bước 1 — đọc tên hàng (hoặc cột đầu) để biết đang nói về cái gì.","Bước 2 — đọc con số ở cột tương ứng với đối tượng đó.","Bước 3 — muốn biết “tất cả”, “nhiều nhất”, “ít nhất” thì phải CỘNG hoặc SO các con số, không đọc lại một ô.","Kiểm tra lại: tổng vừa tính phải LỚN HƠN từng con số trong bảng."]}},{"type":"quiz","content":{"question":"Trong bảng trên, số lượng nào LỚN NHẤT?","options":[1,3,4,6],"answer":3,"mascotHint":"Bé so các con số 1, 2, 3 — số lớn nhất là 3.","table":{"headers":["Bước","Việc làm"],"rows":[["1","Thu thập số liệu"],["2","Phân loại"],["3","Kiểm đếm"]]}}},{"type":"quiz","content":{"question":"Cộng các con số trong bảng lại thì được bao nhiêu?","options":[3,5,6,7],"answer":6,"mascotHint":"Lấy các con số cộng lại: 1 + 2 + 3 = 6.","table":{"headers":["Bước","Việc làm"],"rows":[["1","Thu thập số liệu"],["2","Phân loại"],["3","Kiểm đếm"]]}}},{"type":"quiz","content":{"question":"4 × 4 bằng bao nhiêu?","options":[6,15,16,17],"answer":16,"mascotHint":"hàng đơn vị 4 × 4 = 16, viết 6 nhớ 1. Kết quả 16."}},{"type":"quiz","content":{"question":"Trên biểu đồ, mỗi hình là 5 quả bóng. Nhóm có 4 hình. Hỏi nhóm đó có bao nhiêu quả bóng?","options":[9,20,45,54],"answer":20,"items":[{"emoji":"⚽","count":4}],"mascotHint":"4 × 5 = 20 quả bóng."}},{"type":"quiz","content":{"question":"Bé gieo một đồng xu, mặt sấp ngửa. Điều này thuộc mức nào?","options":["Chắc chắn","Có thể","Không thể","Không xác định"],"answer":"Có thể","mascotHint":"Đồng xu có thể ra mặt sấp hoặc mặt ngửa — đều có thể xảy ra.","items":[{"emoji":"🪙","label":"Đồng xu","count":1}]}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Đếm hình rồi nhân với số lượng mỗi hình.","Bé đã hoàn thành chủ đề 13."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g3-c15-l1', 'g3-c15', 'Bài 1: Bảng số liệu', 'learn', 'Đọc và nhận xét số liệu trong bảng', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Lớp 3A có 12 bạn thích bóng đá, 8 bạn thích cầu lông. Bé xem bảng để biết ai đông hơn nhé! 📊"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Bảng số liệu","explanation":"BẢNG SỐ LIỆU cho biết số lượng của từng đối tượng. Bé đọc theo hàng và cột để so sánh.","rule":"Lớp 3A: bóng đá 12 bạn; cầu lông 8 bạn; bơi 5 bạn. Môn được thích nhất là bóng đá.","points":["Cột bên trái ghi tên đối tượng.","Cột bên phải ghi số lượng.","Nhìn số lớn nhất để biết đối tượng nhiều nhất."]}},{"type":"visual","content":{"text":"Bóng đá: 12 bạn\nCầu lông: 8 bạn\nBơi     : 5 bạn","table":{"headers":["Môn","Số bạn"],"rows":[["Bóng đá",12],["Cầu lông",8],["Bơi",5]],"label":"Bảng số liệu lớp 3A — môn được nhiều bạn thích nhất là bóng đá"}}},{"type":"visual","content":{"cotTinh":{"left":12,"right":8,"sign":"−"},"text":"Bé tự đặt tính: 12 − 8\nhàng đơn vị 2 < 8 nên mượn 1: 12 − 8 = 4, viết 4\nhàng chục 1 − 1 = 0, viết 0\nVậy 12 − 8 = 4."}},{"type":"concept","content":{"badge":"Chú Ý","title":"Vì sao ra 14 là sai?","explanation":"14 là kết quả khi bé quên bớt 1 chục sau khi mượn. Đây là lỗi hay gặp nhất của dạng trừ này.","points":["Lỗi — quên bớt 1 chục sau khi mượn: hàng đơn vị 2 < 8 nên mượn 1: 12 − 8 = 4, viết 4. Kết quả đúng phải là 4.","Cách tránh: làm xong một hàng thì ghi/xoá số đã vay NGAY, đừng để sang hàng sau mới nhớ.","Tự kiểm tra: 4 + 8 phải bằng 12."]}},{"type":"visual","content":{"table":{"headers":["Môn","Số bạn"],"rows":[["Bóng đá",12],["Cầu lông",8],["Bơi",5]],"label":"Bảng số liệu lớp 3A — môn được nhiều bạn thích nhất là bóng đá"},"text":"Bảng số liệu của bài — bé đọc theo HÀNG, không đọc theo cột\nMuốn biết “tất cả”, “nhiều nhất”, “ít nhất” thì phải cộng hoặc so các con số.\nVí dụ: 12 + 8 + 5 = 25."}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Cách đọc bảng số liệu","explanation":"Bảng số liệu là một bức tranh bằng số: mỗi hàng là một đối tượng, mỗi cột là một thông tin.","points":["Bước 1 — đọc tên hàng (hoặc cột đầu) để biết đang nói về cái gì.","Bước 2 — đọc con số ở cột tương ứng với đối tượng đó.","Bước 3 — muốn biết “tất cả”, “nhiều nhất”, “ít nhất” thì phải CỘNG hoặc SO các con số, không đọc lại một ô.","Kiểm tra lại: tổng vừa tính phải LỚN HƠN từng con số trong bảng."]}},{"type":"quiz","content":{"question":"Trong bảng trên, số lượng nào LỚN NHẤT?","options":[5,12,13,25],"answer":12,"mascotHint":"Bé so các con số 12, 8, 5 — số lớn nhất là 12.","table":{"headers":["Môn","Số bạn"],"rows":[["Bóng đá",12],["Cầu lông",8],["Bơi",5]]}}},{"type":"quiz","content":{"question":"Cộng các con số trong bảng lại thì được bao nhiêu?","options":[12,24,25,26],"answer":25,"mascotHint":"Lấy các con số cộng lại: 12 + 8 + 5 = 25.","table":{"headers":["Môn","Số bạn"],"rows":[["Bóng đá",12],["Cầu lông",8],["Bơi",5]]}}},{"type":"quiz","content":{"question":"16 − 7 bằng bao nhiêu?","options":[8,9,10,19],"answer":9,"mascotHint":"hàng đơn vị 6 < 7 nên mượn 1: 16 − 7 = 9, viết 9. Kết quả 9."}},{"type":"quiz","content":{"question":"Trong bảng trên (bóng đá 12, cầu lông 8, bơi 5), số bạn thích bóng đá hơn số bạn thích cầu lông là bao nhiêu?","options":["4 bạn","6 bạn","8 bạn","20 bạn"],"answer":"4 bạn","mascotHint":"12 − 8 = 4 bạn.","table":{"headers":["Môn","Số bạn"],"rows":[["Bóng đá",12],["Cầu lông",8],["Bơi",5]],"label":"Bảng số liệu lớp 3A — môn được nhiều bạn thích nhất là bóng đá"}}},{"type":"summary","content":{"title":"Bé nhớ rất tốt:","points":["Bảng số liệu cho biết số lượng của từng đối tượng.","12 − 8 = 4 bạn."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g4-c3-l7', 'g4-c3', 'Bài 16: Luyện tập chung', 'learn', 'Ôn tập tổng hợp: hàng và lớp, so sánh số, làm tròn số, dãy số tự nhiên', 6, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Hôm nay chúng mình ôn lại toàn bộ Chủ đề 3: hàng, lớp, so sánh số, làm tròn số và dãy số tự nhiên. Cùng làm thử thách của Rô-bốt nhé! 🤖"}},{"type":"visual","content":{"text":"Hoàn thành bảng: giá trị của chữ số theo hàng","table":{"headers":["Số","Chữ số","Giá trị"],"rows":[[182729119,8,"80 000 000"],[74810331,4,"4 000 000"],[3037933,3,"3 000 000"],[981381070,9,"900 000 000"]],"label":"Giá trị = chữ số × giá trị của hàng"}}},{"type":"visual","content":{"baseTen":{"tens":1,"ones":6},"text":"16 gồm mấy chục và mấy đơn vị?\nBé đếm khối: 1 thanh chục và 6 ô rời\nVậy 16 = 1 chục và 6 đơn vị"}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"So sánh hai số cho đúng","explanation":"Muốn biết số nào lớn hơn, bé làm hai bước sau — không cần đếm lại từ đầu.","points":["Bước 1 — đếm số chữ số: số nào có ít chữ số hơn thì số đó BÉ hơn (ví dụ 9 < 10).","Bước 2 — hai số cùng số chữ số: so chữ số đầu tiên bên TRÁI trước; số nào có chữ số ấy lớn hơn thì số đó lớn hơn. Bằng nhau thì so chữ số tiếp theo.","Ví dụ: 16 có 2 chữ số, 3 có 1 chữ số — số nào có ít chữ số hơn thì bé hơn.","Số liền sau = số đó thêm 1; số liền trước = số đó bớt 1."]}},{"type":"quiz","content":{"question":"Số liền sau của số 16 là số nào?","options":[16,17,18,26],"answer":17,"mascotHint":"Số liền sau hơn số đã cho 1 đơn vị: 16 + 1 = 17."}},{"type":"quiz","content":{"question":"Số nào LỚN NHẤT trong các số sau: 16, 3, 7, 2?","options":["2","3","7","16"],"answer":"16","mascotHint":"Bé so chữ số đầu tiên bên trái của các số, bằng nhau thì so chữ số tiếp theo — số lớn nhất là 16."}},{"type":"quiz","content":{"question":"Số nào lớn nhất trong các số sau?","options":["738 829 192","391 130 031","250 030 000","222 222 222"],"answer":"738 829 192","mascotHint":"Cả bốn số đều chín chữ số, so hàng trăm triệu: 7 > 3 > 2 nên 738 829 192 lớn nhất."}},{"type":"quiz","content":{"question":"Làm tròn số 451 900 đến hàng trăm nghìn ta được:","options":["400 000","450 000","500 000","460 000"],"answer":"500 000","mascotHint":"Hàng chục nghìn là 5 nên làm tròn lên: 500 000."}},{"type":"quiz","content":{"question":"Trong các số sau, số nào có hai chữ số ở lớp nghìn?","options":["4 519","100 000","45 000","115 806 715"],"answer":"45 000","mascotHint":"45 000 có lớp nghìn gồm hai chữ số 4 và 5 (đọc là bốn mươi lăm nghìn)."}},{"type":"quiz","content":{"question":"Năm học nào có nhiều học sinh tiểu học nhất trong bảng trên?","options":["2016 – 2017","2017 – 2018","2018 – 2019","2019 – 2020"],"answer":"2019 – 2020","mascotHint":"8 741 545 là số lớn nhất trong bảng, thuộc năm học 2019 – 2020.","table":{"headers":["Năm học","Số học sinh tiểu học"],"rows":[["2016 – 2017",7801560],["2017 – 2018",8041842],["2018 – 2019",8541451],["2019 – 2020",8741545]],"label":"Số học sinh tiểu học qua các năm học"}}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Cứ ba hàng là một lớp: đơn vị · nghìn · triệu.","So sánh số: so từ hàng lớn nhất trở xuống.","Làm tròn và tìm số liền trước, liền sau thành thạo."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g4-c6-l4', 'g4-c6', 'Bài 30: Hình bình hành', 'learn', 'Nhận biết hình bình hành: hai cặp cạnh đối diện song song và bằng nhau', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Cú Mèo ghép hình con gà từ các miếng bìa. Đuôi con gà có dạng một hình đặc biệt — đó là hình bình hành! 🐔"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Hình bình hành ABCD","explanation":"Hình bình hành có hai cặp cạnh đối diện song song với nhau và hai cặp cạnh đối diện bằng nhau. Trong hình bình hành ABCD: AB song song với DC, AD song song với BC, và AB = DC, AD = BC.","points":["AB và DC là hai cạnh đối diện; AD và BC cũng là hai cạnh đối diện.","Cạnh AB song song với cạnh DC; cạnh AD song song với cạnh BC.","AB = DC và AD = BC."],"rule":"Hình bình hành: hai cặp cạnh đối diện vừa SONG SONG vừa BẰNG NHAU.","planeShape":{"kind":"parallelogram","labels":["AB","BC","CD","DA"],"vertexLabels":["A","B","C","D"],"formula":"Hình bình hành ABCD: AB song song và bằng DC; AD song song và bằng BC"}}},{"type":"visual","content":{"text":"Các cặp cạnh của hình bình hành ABCD","planeShape":{"kind":"parallelogram","labels":["AB","BC","CD","DA"],"vertexLabels":["A","B","C","D"],"formula":"Hình bình hành ABCD có hai cặp cạnh đối diện song song và bằng nhau"},"table":{"headers":["Cặp cạnh đối diện","Quan hệ"],"rows":[["AB và DC","song song và bằng nhau"],["AD và BC","song song và bằng nhau"]],"label":"Hình bình hành ABCD có hai cặp cạnh đối diện song song, bằng nhau"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài bài toán có lời văn đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Đọc kỹ đề, gạch dưới các SỐ và từ khoá (thêm, bớt, gấp, chia đều).","Bước 2 — Tóm tắt đề bằng hình hoặc bằng câu ngắn: đã có gì, cần tìm gì.","Bước 3 — Chọn phép tính: “thêm, gộp, tất cả” → cộng; “bớt, cho đi, còn lại” → trừ; “gấp mấy lần” → nhân.","Bước 4 — Đặt tính rồi tính, rồi VIẾT ĐÁP SỐ kèm đơn vị và thử lại bằng phép ngược."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["Đơn vị","đáp số luôn kèm đơn vị như con, quả, kg, cm"],["Kiểm tra","cộng thì lấy kết quả trừ đi một số hạng"],["Câu trả lời","viết đủ câu, không chỉ ghi số"]]},"text":"Bảng nhớ nhanh — bài toán có lời văn\nBa điều dưới đây bé đọc lại mỗi khi làm bài.\nTrước khi nộp bài, bé tự hỏi: đã đủ ba điều này chưa?"}},{"type":"quiz","content":{"question":"Giải một bài toán có lời văn, bé làm gì TRƯỚC TIÊN?","options":["Đọc kỹ đề và gạch dưới các số đã cho","Viết ngay đáp số","Đoán kết quả","Đặt tính trước khi đọc đề"],"answer":"Đọc kỹ đề và gạch dưới các số đã cho","mascotHint":"Chưa đọc kỹ đề thì chưa biết đề cho gì, hỏi gì — mọi bước sau đều dễ sai."}},{"type":"quiz","content":{"question":"Hình bình hành có đặc điểm gì về các cạnh đối diện?","planeShape":{"kind":"parallelogram","labels":["AB","BC","CD","DA"],"vertexLabels":["A","B","C","D"]},"options":["Song song và bằng nhau","Cắt nhau","Vuông góc với nhau","Không bằng nhau"],"answer":"Song song và bằng nhau","mascotHint":"Hai cặp cạnh đối diện của hình bình hành song song và bằng nhau."}},{"type":"quiz","content":{"question":"Một hình bình hành có một cạnh dài 3 dm. Cạnh đối diện với cạnh đó dài bao nhiêu đề-xi-mét?","planeShape":{"kind":"parallelogram","labels":["3 dm","?","3 dm","?"]},"options":["3 dm","6 dm","1,5 dm","9 dm"],"mascotHint":"Hai cạnh đối diện của hình bình hành thì bằng nhau, nên cạnh đối diện cũng dài 3 dm.","answer":"3 dm"}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Hình bình hành có hai cặp cạnh đối diện song song.","Hai cặp cạnh đối diện đó cũng bằng nhau.","Nhìn thấy cặp cạnh song song và bằng nhau là nghĩ tới hình bình hành."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g4-c7-l5', 'g4-c7', 'Bài 37: Ôn tập một số yếu tố thống kê', 'learn', 'Đọc bảng số liệu, so sánh số liệu, làm tròn số liệu và trả lời câu hỏi', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Bảng số liệu cho biết nhiều điều thú vị: nước nào có nhiều khách du lịch nhất, tỉnh nào đông dân nhất… Cùng đọc bảng như đọc một câu chuyện nhé! 📊"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Đọc bảng số liệu","explanation":"Khi đọc bảng số liệu, bé nhìn tên cột và tên dòng trước, rồi so sánh các số trong bảng để trả lời câu hỏi: số nào lớn nhất, số nào bé nhất, hơn kém nhau bao nhiêu.","points":["Đọc kĩ tiêu đề bảng để biết số liệu nói về cái gì.","So sánh các số: số có nhiều chữ số hơn thì lớn hơn.","Có thể làm tròn số liệu để dễ nhớ: 8 891 344 ≈ 8 891 000 (hàng nghìn)."],"rule":"Đọc tên cột → đọc số → so sánh → trả lời."}},{"type":"visual","content":{"text":"Lượt khách du lịch đến Việt Nam năm 2019","table":{"headers":["Nước","Số lượt khách"],"rows":[["Lào",98500],["Cam-pu-chia",227900],["Phi-líp-pin",509600],["Ma-lai-xi-a",606200]],"label":"Ma-lai-xi-a nhiều nhất · Lào ít nhất"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài bài toán có lời văn đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Đọc kỹ đề, gạch dưới các SỐ và từ khoá (thêm, bớt, gấp, chia đều).","Bước 2 — Tóm tắt đề bằng hình hoặc bằng câu ngắn: đã có gì, cần tìm gì.","Bước 3 — Chọn phép tính: “thêm, gộp, tất cả” → cộng; “bớt, cho đi, còn lại” → trừ; “gấp mấy lần” → nhân.","Bước 4 — Đặt tính rồi tính, rồi VIẾT ĐÁP SỐ kèm đơn vị và thử lại bằng phép ngược."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["Đơn vị","đáp số luôn kèm đơn vị như con, quả, kg, cm"],["Kiểm tra","cộng thì lấy kết quả trừ đi một số hạng"],["Câu trả lời","viết đủ câu, không chỉ ghi số"]]},"text":"Bảng nhớ nhanh — bài toán có lời văn\nBa điều dưới đây bé đọc lại mỗi khi làm bài.\nTrước khi nộp bài, bé tự hỏi: đã đủ ba điều này chưa?"}},{"type":"quiz","content":{"question":"Giải một bài toán có lời văn, bé làm gì TRƯỚC TIÊN?","options":["Đọc kỹ đề và gạch dưới các số đã cho","Viết ngay đáp số","Đoán kết quả","Đặt tính trước khi đọc đề"],"answer":"Đọc kỹ đề và gạch dưới các số đã cho","mascotHint":"Chưa đọc kỹ đề thì chưa biết đề cho gì, hỏi gì — mọi bước sau đều dễ sai."}},{"type":"quiz","content":{"question":"Theo bảng trên, nước nào có số lượt khách du lịch đến Việt Nam nhiều nhất?","options":["Lào","Cam-pu-chia","Phi-líp-pin","Ma-lai-xi-a"],"answer":"Ma-lai-xi-a","mascotHint":"606 200 là số lớn nhất trong bảng.","table":{"headers":["Nước","Số lượt khách"],"rows":[["Lào",98500],["Cam-pu-chia",227900],["Phi-líp-pin",509600],["Ma-lai-xi-a",606200]]}}},{"type":"quiz","content":{"question":"Số học sinh tiểu học cả nước là 8 891 344. Làm tròn đến hàng trăm ta được:","options":["8 891 300","8 891 400","8 891 000","8 892 000"],"answer":"8 891 300","mascotHint":"Làm tròn đến hàng trăm: nhìn chữ số hàng chục là 4 (< 5) nên giữ nguyên: 8 891 300."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Đọc tiêu đề bảng trước khi so sánh số liệu.","Số nhiều chữ số hơn thì lớn hơn.","Làm tròn giúp số liệu dễ nhớ hơn."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g4-c9-l2', 'g4-c9', 'Bài 50: Biểu đồ cột', 'learn', 'Đọc và nhận xét số liệu trên biểu đồ cột; tìm giá trị trung bình', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Mai khảo sát môn thể thao yêu thích của các bạn và Rô-bốt vẽ thành biểu đồ cột. Cột cao là nhiều bạn yêu thích, cột thấp là ít bạn yêu thích! 📊"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Đọc biểu đồ cột","explanation":"Biểu đồ cột dùng các cột có độ cao khác nhau để biểu diễn số liệu. Muốn biết số liệu của một đối tượng, ta nhìn độ cao của cột tương ứng với các vạch số ở bên trái.","points":["Tên các đối tượng ghi ở dưới trục ngang.","Các vạch số ở trục dọc cho biết giá trị.","Cột càng cao thì số liệu càng lớn."],"rule":"Nhìn trục dọc để đọc số liệu của mỗi cột."}},{"type":"visual","content":{"text":"Số bạn yêu thích mỗi môn thể thao","table":{"headers":["Môn thể thao","Bóng đá","Bóng rổ","Bơi"],"rows":[["Số bạn",4,6,2]],"label":"Bóng rổ được nhiều bạn yêu thích nhất (6 bạn), bơi ít nhất (2 bạn)"}}},{"type":"visual","content":{"text":"Số học sinh đến thư viện mượn sách","table":{"headers":["Ngày","Thứ Hai","Thứ Ba","Thứ Tư","Thứ Năm","Thứ Sáu"],"rows":[["Số học sinh",35,50,50,70,115]],"label":"Thứ Sáu có nhiều học sinh mượn sách nhất: 115 học sinh"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài bài toán có lời văn đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Đọc kỹ đề, gạch dưới các SỐ và từ khoá (thêm, bớt, gấp, chia đều).","Bước 2 — Tóm tắt đề bằng hình hoặc bằng câu ngắn: đã có gì, cần tìm gì.","Bước 3 — Chọn phép tính: “thêm, gộp, tất cả” → cộng; “bớt, cho đi, còn lại” → trừ; “gấp mấy lần” → nhân.","Bước 4 — Đặt tính rồi tính, rồi VIẾT ĐÁP SỐ kèm đơn vị và thử lại bằng phép ngược."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["Đơn vị","đáp số luôn kèm đơn vị như con, quả, kg, cm"],["Kiểm tra","cộng thì lấy kết quả trừ đi một số hạng"],["Câu trả lời","viết đủ câu, không chỉ ghi số"]]},"text":"Bảng nhớ nhanh — bài toán có lời văn\nBa điều dưới đây bé đọc lại mỗi khi làm bài.\nTrước khi nộp bài, bé tự hỏi: đã đủ ba điều này chưa?"}},{"type":"quiz","content":{"question":"Giải một bài toán có lời văn, bé làm gì TRƯỚC TIÊN?","options":["Đọc kỹ đề và gạch dưới các số đã cho","Viết ngay đáp số","Đoán kết quả","Đặt tính trước khi đọc đề"],"answer":"Đọc kỹ đề và gạch dưới các số đã cho","mascotHint":"Chưa đọc kỹ đề thì chưa biết đề cho gì, hỏi gì — mọi bước sau đều dễ sai."}},{"type":"quiz","content":{"question":"Dựa vào bảng số liệu trên, môn thể thao nào được nhiều bạn yêu thích nhất?","options":["Bóng rổ","Bóng đá","Bơi","Bóng đá và bơi"],"answer":"Bóng rổ","mascotHint":"Bóng rổ 6 bạn, nhiều hơn bóng đá 4 bạn và bơi 2 bạn.","table":{"headers":["Môn thể thao","Bóng đá","Bóng rổ","Bơi"],"rows":[["Số bạn",4,6,2]]}}},{"type":"quiz","content":{"question":"Số học sinh đến thư viện mượn sách trong 5 ngày là 35; 50; 50; 70; 115. Trung bình mỗi ngày có bao nhiêu học sinh?","options":["64 học sinh","60 học sinh","70 học sinh","320 học sinh"],"answer":"64 học sinh","mascotHint":"(35 + 50 + 50 + 70 + 115) : 5 = 320 : 5 = 64 (học sinh)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Cột cao = số liệu lớn.","Đọc số liệu theo trục dọc.","Có thể tính trung bình cộng từ số liệu trên biểu đồ."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g4-c9-l3', 'g4-c9', 'Bài 51: Số lần xuất hiện của một sự kiện', 'learn', 'Liệt kê các sự kiện có thể xảy ra và đếm số lần xuất hiện bằng bảng kiểm đếm', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Trong hộp có 3 quả bóng xanh và 1 quả bóng vàng. Rô-bốt lấy 1 quả bóng ra xem màu rồi trả lại. Làm 10 lần, bạn ấy ghi kết quả vào bảng kiểm đếm. 🎈"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Liệt kê sự kiện và đếm số lần","explanation":"Khi thực hiện một hoạt động ngẫu nhiên, ta liệt kê các sự kiện có thể xảy ra, sau đó dùng bảng kiểm đếm để ghi lại mỗi lần sự kiện nào xuất hiện.","points":["Lấy 1 bóng: có 2 sự kiện có thể xảy ra là bóng xanh hoặc bóng vàng.","Lấy 2 bút từ túi có 2 bút xanh và 1 bút vàng: có thể được 2 bút xanh, hoặc 1 bút xanh và 1 bút vàng.","Mỗi lần ghi bằng một gạch, sau đó đếm để biết số lần xuất hiện."],"rule":"Liệt kê sự kiện → ghi kiểm đếm → đếm số lần."}},{"type":"visual","content":{"text":"Bảng kiểm đếm khi quay mũi tên 20 lần","table":{"headers":["Phần mũi tên dừng lại","Số lần"],"rows":[["Phần màu đỏ",9],["Phần màu vàng",11]],"label":"Cả hai sự kiện đều xảy ra; vàng xuất hiện nhiều hơn đỏ"}}},{"type":"visual","content":{"table":{"headers":["Phần mũi tên dừng lại","Số lần"],"rows":[["Phần màu đỏ",9],["Phần màu vàng",11]],"label":"Cả hai sự kiện đều xảy ra; vàng xuất hiện nhiều hơn đỏ"},"text":"Bảng số liệu của bài — bé đọc theo HÀNG, không đọc theo cột\nMuốn biết “tất cả”, “nhiều nhất”, “ít nhất” thì phải cộng hoặc so các con số.\nVí dụ: 9 + 11 = 20."}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Cách đọc bảng số liệu","explanation":"Bảng số liệu là một bức tranh bằng số: mỗi hàng là một đối tượng, mỗi cột là một thông tin.","points":["Bước 1 — đọc tên hàng (hoặc cột đầu) để biết đang nói về cái gì.","Bước 2 — đọc con số ở cột tương ứng với đối tượng đó.","Bước 3 — muốn biết “tất cả”, “nhiều nhất”, “ít nhất” thì phải CỘNG hoặc SO các con số, không đọc lại một ô.","Kiểm tra lại: tổng vừa tính phải LỚN HƠN từng con số trong bảng."]}},{"type":"quiz","content":{"question":"Trong bảng trên, số lượng nào LỚN NHẤT?","options":[9,11,12,20],"answer":11,"mascotHint":"Bé so các con số 9, 11 — số lớn nhất là 11.","table":{"headers":["Phần mũi tên dừng lại","Số lần"],"rows":[["Phần màu đỏ",9],["Phần màu vàng",11]]}}},{"type":"quiz","content":{"question":"Cộng các con số trong bảng lại thì được bao nhiêu?","options":[11,20,21,22],"answer":20,"mascotHint":"Lấy các con số cộng lại: 9 + 11 = 20.","table":{"headers":["Phần mũi tên dừng lại","Số lần"],"rows":[["Phần màu đỏ",9],["Phần màu vàng",11]]}}},{"type":"quiz","content":{"question":"Trong hộp có 3 bóng xanh, 1 bóng vàng. Lấy 1 quả bóng ra, có mấy sự kiện có thể xảy ra?","options":["2 sự kiện","1 sự kiện","3 sự kiện","4 sự kiện"],"answer":"2 sự kiện","mascotHint":"Hoặc lấy được bóng xanh, hoặc lấy được bóng vàng — 2 sự kiện."}},{"type":"quiz","content":{"question":"Quay mũi tên 20 lần, kết quả là 9 lần dừng ở màu đỏ và 11 lần ở màu vàng. Sự kiện nào xuất hiện nhiều lần hơn?","options":["Màu vàng","Màu đỏ","Bằng nhau","Không xác định"],"answer":"Màu vàng","mascotHint":"11 > 9 nên màu vàng xuất hiện nhiều hơn 2 lần."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Liệt kê hết các sự kiện có thể xảy ra.","Ghi lại bằng bảng kiểm đếm.","So sánh số lần xuất hiện của các sự kiện."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c11-l3', 'g5-c11', 'Bài 65: Tỉ số của số lần lặp lại một sự kiện so với tổng số lần thực hiện', 'learn', 'Ghi lại kết quả thực hiện nhiều lần và tính tỉ số của số lần một sự kiện lặp lại', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Rô-bốt gieo xúc xắc 20 lần, có 4 lần xuất hiện mặt 5 chấm. Vậy tỉ số là 4/20 tức 1/5. 🎲"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Tỉ số của số lần lặp lại","explanation":"Khi thực hiện một hoạt động nhiều lần, ta ghi lại số lần mỗi sự kiện xảy ra. Tỉ số của số lần lặp lại một sự kiện so với tổng số lần thực hiện là số lần sự kiện đó xảy ra chia cho tổng số lần thực hiện.","points":["Gieo xúc xắc 20 lần, mặt 5 chấm xuất hiện 4 lần ⇒ tỉ số 4/20 = 1/5.","Tổng các tỉ số của mọi sự kiện bằng 1.","Có thể viết tỉ số dưới dạng phân số hoặc tỉ số phần trăm."],"rule":"Tỉ số = số lần sự kiện xảy ra : tổng số lần thực hiện."}},{"type":"visual","content":{"text":"Kết quả gieo xúc xắc 20 lần","table":{"headers":["Số chấm","Số lần xuất hiện","Tỉ số so với 20 lần"],"rows":[["1 chấm",3,"3/20"],["3 chấm",5,"5/20 = 1/4"],["5 chấm",4,"4/20 = 1/5"]],"label":"Tổng số lần ghi được của các mặt bằng 20"}}},{"type":"visual","content":{"table":{"headers":["Số chấm","Số lần xuất hiện","Tỉ số so với 20 lần"],"rows":[["1 chấm",3,"3/20"],["3 chấm",5,"5/20 = 1/4"],["5 chấm",4,"4/20 = 1/5"]],"label":"Tổng số lần ghi được của các mặt bằng 20"},"text":"Bảng số liệu của bài — bé đọc theo HÀNG, không đọc theo cột\nMuốn biết “tất cả”, “nhiều nhất”, “ít nhất” thì phải cộng hoặc so các con số.\nVí dụ: 3 + 5 + 4 = 12."}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Cách đọc bảng số liệu","explanation":"Bảng số liệu là một bức tranh bằng số: mỗi hàng là một đối tượng, mỗi cột là một thông tin.","points":["Bước 1 — đọc tên hàng (hoặc cột đầu) để biết đang nói về cái gì.","Bước 2 — đọc con số ở cột tương ứng với đối tượng đó.","Bước 3 — muốn biết “tất cả”, “nhiều nhất”, “ít nhất” thì phải CỘNG hoặc SO các con số, không đọc lại một ô.","Kiểm tra lại: tổng vừa tính phải LỚN HƠN từng con số trong bảng."]}},{"type":"quiz","content":{"question":"Trong bảng trên, số lần xuất hiện LỚN NHẤT là mấy lần?","options":[3,4,5,12],"answer":5,"mascotHint":"Bé so số lần xuất hiện: 3, 5, 4 — số lớn nhất là 5 lần (mặt 3 chấm).","table":{"headers":["Số chấm","Số lần xuất hiện","Tỉ số so với 20 lần"],"rows":[["1 chấm",3,"3/20"],["3 chấm",5,"5/20 = 1/4"],["5 chấm",4,"4/20 = 1/5"]]}}},{"type":"quiz","content":{"question":"Cộng các số lần xuất hiện trong bảng lại thì được bao nhiêu lần?","options":[5,11,12,20],"answer":12,"mascotHint":"Lấy các số lần xuất hiện cộng lại: 3 + 5 + 4 = 12 lần.","table":{"headers":["Số chấm","Số lần xuất hiện","Tỉ số so với 20 lần"],"rows":[["1 chấm",3,"3/20"],["3 chấm",5,"5/20 = 1/4"],["5 chấm",4,"4/20 = 1/5"]]}}},{"type":"quiz","content":{"question":"Gieo xúc xắc 20 lần, mặt 5 chấm xuất hiện 4 lần. Tỉ số của số lần xuất hiện mặt 5 chấm so với tổng số lần gieo là:","options":["1/5","1/4","4/5","5/20"],"answer":"1/5","mascotHint":"4/20 rút gọn thành 1/5."}},{"type":"quiz","content":{"question":"Tung đồng xu 50 lần, có 22 lần xuất hiện mặt sấp. Tỉ số của số lần mặt sấp xuất hiện so với tổng số lần tung là:","options":["22/50","28/50","50/22","22/100"],"answer":"22/50","mascotHint":"Tỉ số = 22 : 50 = 22/50."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Ghi lại số lần mỗi sự kiện xảy ra.","Tỉ số = số lần xảy ra : tổng số lần thực hiện.","Có thể rút gọn hoặc đổi thành tỉ số phần trăm."],"mascotMood":"proud"}}]}'::jsonb, NOW())
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  lesson_type = EXCLUDED.lesson_type,
  description = EXCLUDED.description,
  sort_order = EXCLUDED.sort_order,
  status = EXCLUDED.status,
  payload = EXCLUDED.payload,
  updated_at = NOW();

-- Tăng content_version để báo cho web Vercel và máy học sinh nạp ngay bản mới
UPDATE public.app_config
SET value = to_jsonb(
      COALESCE(
        CASE WHEN jsonb_typeof(value) = 'number' THEN (value #>> '{}')::INT END,
        CASE WHEN jsonb_typeof(value) = 'object' THEN (value ->> 'value')::INT END,
        0
      ) + 1
    ),
    updated_at = NOW()
WHERE key = 'content_version'
RETURNING (value #>> '{}')::INT AS phien_ban_moi;

-- Kiểm tra lại trạng thái cấu hình
SELECT key, value FROM public.app_config
WHERE key IN ('content_source', 'content_version') ORDER BY key;
